import requests
import json
def task_func(myString, API_KEY):
    urls = re.findall(r'http[s]?://(?:[a-zA-Z]|[0-9]|[$-_@.&+]|[!*\(\),]|(?:%[0-9a-fA-F][0-9a-fA-F]))+', myString)
    domains = {urllib.parse.urlparse(url).netloc for url in urls}

    geolocation_results = {}
    for domain in domains:
        try:
            url = f"http://api.ipstack.com/{domain}?access_key={API_KEY}"
            response = requests.get(url)
            if response.status_code == 200:
                data = response.json()
                geolocation_results[domain] = data
            else:
                geolocation_results[domain] = None
        except Exception:
            geolocation_results[domain] = None

    return geolocation_results

