import http.server
import json
def task_func():
    class DataHandler(http.server.BaseHTTPRequestHandler):
        def do_POST(self):
            content_type = self.headers.get('Content-Type')
            if content_type != 'application/json':
                self.send_response(400)
                self.send_header('Content-Type', 'application/json')
                self.end_headers()
                response = {
                    "status": "error",
                    "message": "Content-Type header is not application/json"
                }
                self.wfile.write(json.dumps(response).encode('utf-8'))
                return

            content_length = int(self.headers.get('Content-Length', 0))
            post_data = self.rfile.read(content_length)

            try:
                data = json.loads(post_data)
            except json.JSONDecodeError:
                data = {}

            if 'data' not in data:
                self.send_response(400)
                self.send_header('Content-Type', 'application/json')
                self.end_headers()
                response = {
                    "status": "error",
                    "message": "No data received"
                }
                self.wfile.write(json.dumps(response).encode('utf-8'))
                return

            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            response = {
                "status": "success",
                "message": "Data received successfully."
            }
            self.wfile.write(json.dumps(response).encode('utf-8'))

    return DataHandler

import collections
import json
import os
def task_func(directory_path: str) -> dict:
    key_counts = collections.Counter()
    for filename in os.listdir(directory_path):
        if filename.endswith('.json'):
            file_path = os.path.join(directory_path, filename)
            with open(file_path, 'r') as f:
                data = json.load(f)
                if isinstance(data, dict):
                    key_counts.update(data.keys())
                elif isinstance(data, list):
                    for item in data:
                        if isinstance(item, dict):
                            key_counts.update(item.keys())
    return dict(key_counts)

import itertools
import json
def task_func(json_list, r):
    try:
        data = json.loads(json_list)
    except (json.JSONDecodeError, TypeError):
        raise Exception("Invalid JSON")

    if not data or 'number_list' not in data:
        raise Exception("JSON is empty or does not have 'number_list' key")

    number_list = data['number_list']
    combinations = list(itertools.combinations(number_list, r))

    return combinations

import json
import os
import re
def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):

    if not os.path.exists(file_path):
        raise ValueError("File does not exist")

    with open(file_path, 'r') as f:
        data = json.load(f)

    for field in INPUT_JSON.get("required", []):
        if field not in data:
            raise ValueError(f"Required attribute '{field}' is missing")

    properties = INPUT_JSON.get("properties", {})
    for key, config in properties.items():
        if key in data:
            if not isinstance(data[key], config["type"]):
                raise ValueError(f"Type mismatch for attribute '{key}'")

    if "email" in data:
        if not re.match(EMAIL_REGEX, str(data["email"])):
            raise ValueError("Invalid email format")

    if attribute not in data:
        raise ValueError(f"Attribute '{attribute}' not found in JSON")

    return data[attribute]

import re
import json
import os
def task_func(file_path: str, regex_pattern=r'\(.+?\)|\w') -> dict:
    filename = os.path.basename(file_path)

    try:
        with open(file_path, 'r') as f:
            data = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return {filename: []}

    content_str = str(data)
    matches = re.findall(regex_pattern, content_str)

    return {filename: matches}

